      specifier: literal ? expression.text : "<dynamic>",
      line: pos.line + 1,
      column: pos.character + 1,
      dynamic: !literal,
      typeOnly,
      binding: JSON.stringify({ kind, typeOnly, symbols: [...symbols].sort() }),
