  return rows;
}

export function checkDependencies(
  ts: typeof TypeScript,
  input: ArchitectureInput,
): ArchitectureViolation[] {
  const rows: ArchitectureViolation[] = [],
    files = new Map(input.files.map((file) => [file.path, file])),
