      requested,
      ...[".ts", ".tsx", ".mts", ".cts", ".d.ts", ".js", ".jsx", ".mjs", ".cjs", ".json"].map(
        (ext) => requested + ext,
      ),
      stripped + ".ts",
      stripped + ".tsx",
      stripped + ".mts",
      stripped + ".cts",
      ...["index.ts", "index.tsx", "index.mts", "index.cts", "index.js"].map(
