    rows.push(
      violation(
        rule,
        file,
        ref.line,
        ref.column,
        detail,
        `${ref.specifier}\0${target ?? ""}\0${ref.binding}`,
        { specifier: ref.specifier, binding: ref.binding, ...(target ? { target } : {}) },
      ),
    );
