        from: pkg.root,
        to: target.root,
        file: pkg.root ? `${pkg.root}/package.json` : "package.json",
        target: target.root ? `${target.root}/package.json` : "package.json",
        ref: {
          specifier: dependency,
          line: 1,
          column: 1,
          dynamic: false,
          typeOnly: false,
          binding: JSON.stringify({
            kind: "manifest-production",
            typeOnly: false,
            symbols: [dependency],
