            file.path.startsWith("tooling/") &&
            ref.typeOnly &&
            spec === "typescript" &&
            requested.every((value) => value.endsWith("/backend/node_modules/typescript")) &&
            packages.some((pkg) => pkg.dependencies.has("typescript"));
